// Generated wind texture: Magnific / ElevenLabs. 24 kHz mono PCM.
const bytes=Uint8Array.from(atob(''),c=>c.charCodeAt(0));
const view=new DataView(bytes.buffer);
export const windSample=Float32Array.from({length:bytes.length/2},(_,i)=>view.getInt16(i*2,true)/32768);
export const windSampleRate=24000;
// Normalize the asset once; user-facing volume remains a mix control, independent of source loudness.
let energy=0,peak=0;for(const x of windSample){energy+=x*x;peak=Math.max(peak,Math.abs(x));}
const trim=Math.min(.17/Math.max(1e-8,Math.sqrt(energy/windSample.length)),.95/Math.max(1e-8,peak));
for(let i=0;i<windSample.length;i++)windSample[i]*=trim;
